# This code has been fully generated by an AI.
"""Zwei feste Roboter-Slots, verfolgt in der entzerrten Arena.

Alles, was sich vom einfarbigen Boden abhebt, ist ein Roboter. Welcher welcher ist, folgt aus der
Bewegung; nach einer Berührung und ab und zu zur Kontrolle entscheidet das Aussehen. EdgeTAM kann
optional nebenher als Schiedsrichter laufen, ohne das Tracking je warten zu lassen.
Dazu die Regeln, die die Identität im Gedächtnis von EdgeTAM sauber halten.
"""

import itertools
import logging
import math
import threading
from collections import deque
from dataclasses import dataclass, field

import cv2
import numpy as np

from .arena import EDGE, UNITS, Arena, cues, solid

log = logging.getLogger(__name__)

# So schreibt ein Pixel sicher "nicht dieser Roboter" ins Gedächtnis (Sigmoid fast 0).
NO_LOGIT = -10.0
# Dasselbe im 256er-Raster der Modellmasken: lose Räder gehören dazu, eine abgelöste Hand nicht.
GROUP_CELLS = 5
# Weicht die Fläche so stark von der Registrierung ab, hängt eine Hand oder der Gegner mit drin.
AREA_MIN = 0.5
AREA_MAX = 1.6
# Nur tauschen, wenn beide Roboter einzeln klar zur jeweils anderen Registrierung passen.
SWAP_MARGIN = 0.03
ALPHA = 0.6
BETA = 0.3
JUMP_UNITS = 120.0
LOST_AFTER_S = 1.0
CONTACT_UNITS = 12.0
# Verfolgt wird nur die entzerrte Arena: Was außerhalb liegt, kommt gar nicht erst ins Bild.
SCALE = 0.5
MAX_SIDE = 640
MIN_SIDE = 64
# So viel weiter als der ignorierte Randstreifen gilt ein Roboter als an der Arenakante.
EDGE_PX = 2
NEAR_PX = 5
# Kleinere Stücke sind Rauschen oder Krümel, kein Roboter.
MIN_AREA_RATIO = 0.15
# So viele Bilder stimmen über den Vordergrund ab.
STABLE_FRAMES = 3
# Wie weit ein verlorener Roboter springen darf, in Roboter-Durchmessern.
GATE_SIZES = 3.0
# Nach Kontaktende einige Bilder lang prüfen, weil gerade getrennte Roboter oft noch halb verdeckt sind.
REID_AFTER_CONTACT = 6
REID_EVERY = 15
# Nur ein klares EdgeTAM-Urteil zählt; knappe Überlappungen entstehen auch bei richtiger Zuordnung an Rändern.
VERDICT_RATIO = 2.0


# ---------- Regeln für das Modellgedächtnis (reines numpy, ohne Modell testbar) ----------


def exclusive(logits: np.ndarray) -> np.ndarray:
    """Jeder Pixel gehört höchstens einem Roboter; wer dort schwächer ist, bekommt ihn sicher nicht."""
    out = logits.copy()
    if len(out) < 2:
        return out
    winner = out.argmax(axis=0)
    for i in range(len(out)):
        lose = winner != i
        out[i][lose] = np.minimum(out[i][lose], NO_LOGIT)
    return out


def keep_group(mask: np.ndarray, prev: np.ndarray | None) -> np.ndarray:
    """Nur die Teilgruppe behalten, die der Roboter vorher war; abgelöste Fremdteile fallen weg."""
    if not mask.any():
        return mask
    k = 2 * GROUP_CELLS + 1
    groups = cv2.dilate(mask.astype(np.uint8), np.ones((k, k), np.uint8))
    n, labels = cv2.connectedComponents(groups)
    if n <= 2:
        return mask
    # Ohne Überlappung (schnelle Fahrt bei wenig Bildern) zählt die größte Gruppe.
    ref = prev if prev is not None and (prev & mask).any() else mask
    score = np.bincount(labels[mask & ref], minlength=n)
    score[0] = 0
    return mask & (labels == int(np.argmax(score)))


def plausible(area: float, ref_area: float) -> bool:
    return AREA_MIN * ref_area <= area <= AREA_MAX * ref_area


def should_swap(sim: np.ndarray) -> bool:
    """sim[i, j]: Ähnlichkeit der aktuellen Maske i zur Registrierung j."""
    return bool(sim[0, 1] > sim[0, 0] + SWAP_MARGIN and sim[1, 0] > sim[1, 1] + SWAP_MARGIN)


# ---------- Aussehen ----------


def appearance(bgr: np.ndarray, mask: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    """Farbverteilung plus Umriss; beides ändert sich nicht, wenn der Roboter sich dreht."""
    m = mask.astype(np.uint8)
    hist = cv2.calcHist([cv2.cvtColor(bgr, cv2.COLOR_BGR2HSV)], [0, 1], m, [18, 8], [0, 180, 0, 256])
    cv2.normalize(hist, hist)
    return hist, m


def similarity(items: list[tuple[np.ndarray, np.ndarray]], refs: list) -> np.ndarray:
    sim = np.zeros((len(items), len(refs)))
    for i, (bgr, mask) in enumerate(items):
        hist, m = appearance(bgr, mask)
        for j, (rh, rm) in enumerate(refs):
            shape = cv2.matchShapes(m, rm, cv2.CONTOURS_MATCH_I2, 0)
            colour = max(0.0, cv2.compareHist(hist, rh, cv2.HISTCMP_CORREL))
            sim[i, j] = 0.5 * math.exp(-3 * shape) + 0.5 * colour
    return sim


# ---------- Geometrie ----------


def largest_contour(mask: np.ndarray) -> np.ndarray | None:
    contours, _ = cv2.findContours(mask.astype(np.uint8), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    if not contours:
        return None
    return max(contours, key=cv2.contourArea)


def centroid(mask: np.ndarray) -> np.ndarray:
    ys, xs = np.nonzero(mask)
    return np.array([xs.mean(), ys.mean()], np.float32)


def _ellipse(size: int) -> np.ndarray:
    return cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (size, size))


def _overlap(a: np.ndarray, b: np.ndarray) -> float:
    return float((a & b).sum())


def _nearest(groups: list[np.ndarray], p: np.ndarray) -> int:
    """Fleck unter dem Klick oder, wenn daneben geklickt, der nächstgelegene."""
    dist = []
    for g in groups:
        ys, xs = np.nonzero(g)
        dist.append(float(np.min(np.hypot(xs - p[0], ys - p[1]))))
    return int(np.argmin(dist))


def _split(view: np.ndarray, comp: np.ndarray, a: np.ndarray, b: np.ndarray) -> list[np.ndarray]:
    """Einen Fleck mit zwei sich berührenden Robotern an der Farbkante zwischen den Klicks trennen."""
    h, w = comp.shape
    markers = np.zeros((h, w), np.int32)
    markers[~cv2.dilate(comp.astype(np.uint8), _ellipse(7)).astype(bool)] = 1
    for label, p in ((2, a), (3, b)):
        x, y = int(np.clip(p[0], 0, w - 1)), int(np.clip(p[1], 0, h - 1))
        cv2.circle(markers, (x, y), 3, label, -1)
    cv2.watershed(np.ascontiguousarray(view), markers)
    return [comp & (markers == 2), comp & (markers == 3)]


@dataclass
class Track:
    """Ergebnis von EdgeTAM für einen Roboter in einem Bild."""

    mask: np.ndarray
    ok: bool


@dataclass
class Slot:
    id: int
    name: str
    # Aussehen bei der Registrierung; wandert bei einem Tausch mit der Identität.
    ref: tuple
    # Maske in der entzerrten Arena und Bewegung darin, für die Vorhersage im nächsten Bild.
    small: np.ndarray
    area: float
    c: np.ndarray
    v: np.ndarray
    t: float
    pos: np.ndarray | None = None
    vel: np.ndarray = field(default_factory=lambda: np.zeros(2, np.float32))
    outline: np.ndarray | None = None
    radius: float = 0.0
    inside: float = 1.0
    edge: bool = False
    seen_t: float = -math.inf


@dataclass
class RobotObs:
    id: int
    present: bool
    pos: np.ndarray
    vel: np.ndarray
    radius: float
    inside: float
    outline: np.ndarray | None
    # Zuletzt an der Arenakante gesehen: verschwindet er, ist er hinausgefahren.
    edge: bool = False


class Tracker:
    """Hält zwei Roboter-Identitäten über Vordergrund, Bewegung und Aussehen in der entzerrten Arena."""

    def __init__(self, arena: Arena):
        self.arena = arena
        self.arbiter: Arbiter | None = None
        # Halbe Auflösung reicht für Umriss und Position; die Grenzen halten 1080p bei 30 Bildern/s.
        side = float(np.clip(arena.extent * SCALE, MIN_SIDE, MAX_SIDE))
        self.k = side / UNITS
        self.size = arena.pixels(self.k)
        self.matrix = arena.matrix(self.k)
        self.per_px = 1.0 / self.k
        w, h = self.size
        border = np.ones((h, w), bool)
        e = max(1, round(EDGE * max(w, h))) + EDGE_PX
        border[e:-e, e:-e] = False
        self.border = border
        self.near = _ellipse(2 * NEAR_PX + 1)
        self._recent: deque[np.ndarray] = deque(maxlen=STABLE_FRAMES)
        self.proposal: list[np.ndarray | None] = [None, None]
        self._proposal_view: np.ndarray | None = None
        self._lock = threading.Lock()
        self.reset()

    def reset(self) -> None:
        """Neuer Kampf in derselben Arena: Identitäten und Verlauf weg, Entzerrung bleibt."""
        if self.arbiter is not None:
            self.arbiter.close()
        self.arbiter = None
        self.slots: list[Slot] = []
        self.contact = False
        self.merged = False
        self.min_area = 0.0
        self.count = 0
        self.reid_left = 0
        self.swaps = 0
        self.corrections = 0
        self._pending: tuple[int, dict[int, np.ndarray], int] | None = None
        self._recent.clear()
        self.proposal = [None, None]
        self._proposal_view = None

    # ---------- Bildaufbereitung ----------

    def view(self, image: np.ndarray) -> np.ndarray:
        """Entzerrte Draufsicht der Arena; alles außerhalb existiert für das Tracking nicht."""
        return self.arena.warp(image, self.k)

    def foreground(self, view: np.ndarray) -> np.ndarray:
        self._recent.append(cues(view))
        # Mehrheit der letzten Bilder: ein Bild Verzögerung, dafür flackern Ränder und Krümel nicht.
        votes = np.sum(self._recent, axis=0, dtype=np.uint8)
        return solid((2 * votes > len(self._recent)).astype(np.uint8))

    def _groups(self, fg: np.ndarray) -> list[np.ndarray]:
        n, lab, stats, _ = cv2.connectedComponentsWithStats(fg.astype(np.uint8), connectivity=8)
        order = sorted(range(1, n), key=lambda k: -stats[k, cv2.CC_STAT_AREA])
        return [lab == k for k in order if stats[k, cv2.CC_STAT_AREA] >= max(1.0, self.min_area)]

    @staticmethod
    def _crop(view: np.ndarray, small: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
        ys, xs = np.nonzero(small)
        sl = (slice(ys.min(), ys.max() + 1), slice(xs.min(), xs.max() + 1))
        return view[sl], small[sl]

    def outline(self, mask: np.ndarray | None) -> np.ndarray | None:
        """Umriss einer Maske der Draufsicht in Arena-Einheiten."""
        contour = None if mask is None else largest_contour(mask)
        if contour is None:
            return None
        return contour.reshape(-1, 2).astype(np.float32) * self.per_px

    # ---------- Vorschlag vor dem Kampf ----------

    def propose(self, image: np.ndarray, seeds: dict[int, tuple[float, float]]) -> list[np.ndarray | None]:
        """Beide Roboter auf einmal vorschlagen; ein Klick (Arena-Einheiten) legt fest, wer welcher ist."""
        view = self.view(image)
        groups = self._groups(self.foreground(view))
        pts = {i: np.asarray(p, np.float32) * self.k for i, p in seeds.items()}
        picks: list[np.ndarray | None] = [None, None]
        taken: list[int | None] = [None, None]
        for i, p in pts.items():
            if groups:
                taken[i] = _nearest(groups, p)
                picks[i] = groups[taken[i]]
        if len(pts) == 2 and taken[0] is not None and taken[0] == taken[1]:
            # Beide Klicks auf demselben Fleck: die Roboter berühren sich, also an der Farbkante trennen.
            picks = _split(view, groups[taken[0]], pts[0], pts[1])
        rest = [g for k, g in enumerate(groups) if k not in taken]
        free = [i for i in (0, 1) if picks[i] is None]
        for i, g in zip(free, self._order(rest[:len(free)], free), strict=False):
            picks[i] = g
        with self._lock:
            self.proposal = picks
            self._proposal_view = view
        return picks

    def _order(self, groups: list[np.ndarray], free: list[int]) -> list[np.ndarray]:
        """Ungeklickte Roboter behalten ihre Nummer von Bild zu Bild, sonst springen Farben und Namen."""
        if len(groups) < 2 or len(free) < 2:
            return groups
        prev = self.proposal
        cs = [centroid(g) for g in groups]
        if prev[0] is not None and prev[1] is not None:
            pc = [centroid(m) for m in prev]
            keep = np.linalg.norm(cs[0] - pc[0]) + np.linalg.norm(cs[1] - pc[1])
            swap = np.linalg.norm(cs[0] - pc[1]) + np.linalg.norm(cs[1] - pc[0])
            return groups if keep <= swap else groups[::-1]
        # Erstes Bild: links ist Roboter 1.
        return groups if cs[0][0] <= cs[1][0] else groups[::-1]

    def start(self, names: list[str], arbiter: "Arbiter | None", t: float) -> None:
        """Den letzten Vorschlag als die beiden Roboter des Kampfs festhalten."""
        with self._lock:
            view, masks = self._proposal_view, list(self.proposal)
        if view is None or any(m is None or not m.any() for m in masks):
            raise ValueError("Es sind nicht beide Roboter erkannt.")
        self.arbiter = arbiter
        for i, (name, small) in enumerate(zip(names, masks, strict=True)):
            if arbiter is not None:
                x, y, w, h = cv2.boundingRect(small.astype(np.uint8))
                # Der innerste Punkt liegt sicher auf dem Roboter, auch wenn er hufeisenförmig ist.
                dist = cv2.distanceTransform(small.astype(np.uint8), cv2.DIST_L2, 5)
                py, px = np.unravel_index(int(np.argmax(dist)), dist.shape)
                arbiter.add(i + 1, view, [float(x), float(y), float(x + w), float(y + h)],
                            [(float(px), float(py), 1)])
            slot = Slot(i + 1, name, appearance(*self._crop(view, small)), small, float(small.sum()),
                        centroid(small), np.zeros(2, np.float32), t)
            with self._lock:
                self.slots.append(slot)
                self._measure(slot, t)
        with self._lock:
            self.min_area = MIN_AREA_RATIO * min(s.area for s in self.slots)

    def _swap(self) -> None:
        # Bewegung und Umriss bleiben beim Fleck im Bild, nur die Identität wechselt.
        a, b = self.slots
        a.id, b.id = b.id, a.id
        a.name, b.name = b.name, a.name
        a.ref, b.ref = b.ref, a.ref
        a.area, b.area = b.area, a.area
        self.swaps += 1

    # ---------- Pro Bild ----------

    def update(self, image: np.ndarray, t: float) -> tuple[list[RobotObs], bool]:
        view = self.view(image)
        groups = self._groups(self.foreground(view))
        verdict = self.arbiter.verdict() if self.arbiter is not None else None
        with self._lock:
            if not self.slots:
                return [], False
            merged, updated = self._assign(groups, t)
            if self.merged and not merged:
                self.reid_left = REID_AFTER_CONTACT
            self.merged = merged
            self.count += 1
            if len(self.slots) == 2 and not merged and (self.reid_left or self.count % REID_EVERY == 0):
                self.reid_left = max(0, self.reid_left - 1)
                self._check(view)
            if verdict is not None:
                self._fuse(*verdict)
            if (self.arbiter is not None and len(self.slots) == 2 and not merged
                    and self.arbiter.offer(self.count, view)):
                self._pending = (self.count, {s.id: s.small for s in self.slots}, self.swaps)
            for i, slot in enumerate(self.slots):
                if i in updated:
                    self._measure(slot, t)
                else:
                    slot.vel = slot.vel * 0.5
            self.contact = merged or self._touching(t)
            return [self._obs(slot, t) for slot in self.slots], self.contact

    def _predict(self, s: Slot, t: float) -> np.ndarray:
        shift = s.v * (t - s.t)
        mat = np.float32([[1, 0, shift[0]], [0, 1, shift[1]]])
        h, w = s.small.shape
        return cv2.warpAffine(s.small.astype(np.uint8), mat, (w, h), flags=cv2.INTER_NEAREST).astype(bool)

    def _assign(self, groups: list[np.ndarray], t: float) -> tuple[bool, set[int]]:
        """Gruppen den Slots zuordnen; True, wenn beide Roboter zu einer Gruppe verschmolzen sind."""
        n = len(self.slots)
        if not groups:
            return self.merged, set()
        preds = [self._predict(s, t) for s in self.slots]
        near = [cv2.dilate(p.astype(np.uint8), self.near).astype(bool) for p in preds]
        ov = np.array([[_overlap(g, p) for p in near] for g in groups])
        # Für zwei Slots reicht Durchprobieren; erspart eine Abhängigkeit für die Zuordnung.
        rows: list[int | None] = [*range(len(groups)), *[None] * n]
        pick = max(itertools.permutations(rows, n),
                   key=lambda p: sum(ov[r, i] for i, r in enumerate(p) if r is not None))
        matched = {i: r for i, r in enumerate(pick) if r is not None and ov[r, i] > 0}
        new = [np.zeros_like(groups[0]) for _ in self.slots]
        shared = [r for r in range(len(groups)) if (ov[r] > 0).all()]
        merged = False
        if n == 2 and len(matched) < 2 and shared:
            # Beide Vorhersagen liegen auf einer Gruppe: verschmolzen. Pixel gehen an den näheren Vorgänger.
            r = max(shared, key=lambda i: ov[i].sum())
            d = [cv2.distanceTransform((~p).astype(np.uint8), cv2.DIST_L2, 3) for p in preds]
            first = d[0] <= d[1]
            new[0] |= groups[r] & first
            new[1] |= groups[r] & ~first
            used = {r}
            merged = True
        else:
            for i, r in matched.items():
                new[i] |= groups[r]
            used = set(matched.values())
        for r in range(len(groups)):
            if r not in used and ov[r].max() > 0:
                new[int(ov[r].argmax())] |= groups[r]
                used.add(r)
        free = [r for r in range(len(groups)) if r not in used]
        for i, s in enumerate(self.slots):
            if new[i].any() or not free:
                continue
            # Verloren (z. B. schnelle Fahrt bei wenig Bildern): nächste freie Gruppe in Reichweite.
            # Nach längerem Verlust überall, sonst bliebe ein weit weg aufgetauchter Roboter für immer weg.
            pred_c = s.c + s.v * (t - s.t)
            dist = [np.linalg.norm(centroid(groups[r]) - pred_c) for r in free]
            k = int(np.argmin(dist))
            if dist[k] <= GATE_SIZES * np.sqrt(s.area) or t - s.t >= LOST_AFTER_S:
                new[i] |= groups[free.pop(k)]
        updated = set()
        for i, s in enumerate(self.slots):
            if new[i].sum() < max(1.0, self.min_area):
                s.v = s.v * 0.5
                continue
            c = centroid(new[i])
            dt = max(1e-3, t - s.t)
            pred_c = s.c + s.v * dt
            res = c - pred_c
            s.c = (pred_c + ALPHA * res).astype(np.float32)
            s.v = (s.v + BETA * res / dt).astype(np.float32)
            s.small = new[i]
            s.t = t
            updated.add(i)
        return merged, updated

    def _check(self, view: np.ndarray) -> None:
        items = [self._crop(view, s.small) for s in self.slots]
        if any(m.size == 0 or not m.any() for _, m in items):
            return
        if should_swap(similarity(items, [s.ref for s in self.slots])):
            self._swap()

    def _fuse(self, n: int, masks: dict[int, np.ndarray]) -> None:
        """EdgeTAM-Urteil zu einem älteren Bild einarbeiten, ohne einen Tausch seither doppelt zu zählen."""
        pending, self._pending = self._pending, None
        if pending is None or pending[0] != n:
            return
        _, mine, swaps_then = pending
        ids = sorted(mine)
        if len(ids) != 2 or any(i not in masks or not masks[i].any() for i in ids):
            return
        a, b = ids
        w, h = self.size
        tam = {i: masks[i] if masks[i].shape == (h, w) else
               cv2.resize(masks[i].astype(np.uint8), (w, h), interpolation=cv2.INTER_NEAREST).astype(bool)
               for i in ids}
        diag = _overlap(mine[a], tam[a]) + _overlap(mine[b], tam[b])
        cross = _overlap(mine[a], tam[b]) + _overlap(mine[b], tam[a])
        if max(diag, cross) < VERDICT_RATIO * max(1.0, min(diag, cross)):
            return
        wrong = cross > diag
        if wrong != ((self.swaps - swaps_then) % 2 == 1):
            self._swap()
            self.corrections += 1

    def _measure(self, slot: Slot, t: float) -> None:
        # Die Draufsicht ist die Arena, nur in Pixeln; so verfälscht die Perspektive nichts.
        pts = self.outline(slot.small)
        if pts is None:
            return
        m = cv2.moments(pts.reshape(-1, 1, 2))
        if abs(m["m00"]) < 1.0:
            return
        center = np.array([m["m10"] / m["m00"], m["m01"] / m["m00"]], np.float32)
        if slot.pos is None or t - slot.seen_t >= LOST_AFTER_S:
            slot.pos, slot.vel = center, np.zeros(2, np.float32)
        else:
            dt = max(1e-3, t - slot.seen_t)
            pred = slot.pos + slot.vel * dt
            residual = center - pred
            if np.linalg.norm(residual) > JUMP_UNITS:
                # Wiedergefunden ist keine Bewegung; sonst gäbe es Phantom-Kollisionen.
                slot.pos, slot.vel = center, np.zeros(2, np.float32)
            else:
                slot.pos = (pred + ALPHA * residual).astype(np.float32)
                slot.vel = (slot.vel + BETA * residual / dt).astype(np.float32)
        slot.outline = pts
        slot.radius = float(np.sqrt(abs(m["m00"]) / np.pi))
        slot.edge = bool((slot.small & self.border).any())
        # Was über die Kante ragt, ist nicht im Bild; der sichtbare Anteil zeigt, wie viel noch drin ist.
        slot.inside = min(1.0, float(slot.small.sum()) / slot.area) if slot.edge else 1.0
        slot.seen_t = t

    def _present(self, slot: Slot, t: float) -> bool:
        return slot.outline is not None and t - slot.seen_t < LOST_AFTER_S

    def _touching(self, t: float) -> bool:
        live = [s for s in self.slots if self._present(s, t)]
        if len(live) != 2:
            return False
        a, b = (s.outline for s in live)
        return _reaches(a, b) or _reaches(b, a)

    def _obs(self, slot: Slot, t: float) -> RobotObs:
        present = self._present(slot, t) and slot.pos is not None
        pos = slot.pos.copy() if slot.pos is not None else np.zeros(2, np.float32)
        return RobotObs(slot.id, present, pos, slot.vel.copy(), slot.radius, slot.inside,
                        slot.outline if present else None, slot.edge)

    def close(self) -> None:
        if self.arbiter is not None:
            self.arbiter.close()


def _reaches(points: np.ndarray, poly: np.ndarray) -> bool:
    contour = poly.reshape(-1, 1, 2).astype(np.float32)
    return any(cv2.pointPolygonTest(contour, (float(x), float(y)), True) >= -CONTACT_UNITS for x, y in points)


# ---------- EdgeTAM nebenher ----------

# Es gibt nur ein Modell; ein noch laufender Prüfer eines abgebrochenen Kampfs darf den neuen nicht stören.
_MODEL_LOCK = threading.Lock()


class Arbiter:
    """Lässt ein Videomodell im eigenen Thread mitlaufen; das Tracking holt nur fertige Urteile ab."""

    def __init__(self, model, prepare):
        self.model = model
        # Bereitet die Draufsicht fürs Modell auf (z. B. Hintergrund weiß).
        self.prepare = prepare
        self.error: str | None = None
        self.frames = 0
        self._cond = threading.Condition()
        self._job: tuple[int, np.ndarray] | None = None
        self._result: tuple[int, dict[int, np.ndarray]] | None = None
        self._busy = False
        self._stop = False
        with _MODEL_LOCK:
            model.reset_tracking()
        threading.Thread(target=self._work, name="edgetam", daemon=True).start()

    def add(self, obj_id: int, image: np.ndarray, box: list[float] | None,
            points: list[tuple[float, float, int]]) -> None:
        crop = self.prepare(image)
        with _MODEL_LOCK:
            self.model.add_object(obj_id, crop, box, points)

    def offer(self, n: int, image: np.ndarray) -> bool:
        """Nimmt ein Bild nur, wenn das Modell frei ist; sonst läuft das Tracking einfach weiter."""
        with self._cond:
            if self._busy or self._stop or self.error:
                return False
            self._busy = True
            self._job = (n, image)
            self._cond.notify()
            return True

    def verdict(self) -> tuple[int, dict[int, np.ndarray]] | None:
        with self._cond:
            res, self._result = self._result, None
            if res is not None:
                self._busy = False
            return res

    def close(self) -> None:
        with self._cond:
            self._stop = True
            self._cond.notify_all()

    def _work(self) -> None:
        while True:
            with self._cond:
                while self._job is None and not self._stop:
                    self._cond.wait()
                if self._stop:
                    return
                n, image = self._job
                self._job = None
            masks: dict[int, np.ndarray] = {}
            try:
                crop = self.prepare(image)
                with _MODEL_LOCK:
                    if self._stop:
                        return
                    masks = {i: tr.mask for i, tr in self.model.track(crop).items()}
            except Exception as exc:  # noqa: BLE001 – ohne Schiedsrichter läuft das Tracking trotzdem weiter.
                log.exception("EdgeTAM-Prüfung fehlgeschlagen")
                self.error = f"EdgeTAM-Prüfung ausgefallen: {exc}"
            with self._cond:
                self.frames += 1
                self._result = (n, masks)
